/* Bayern Munich DNA — deep red command, bavarian lozenges, mia san mia */
.theme-bayern-munich {
  --bg: oklch(0.418 0.158 20.7);
  --surface: oklch(0.454 0.172 21.0);
  --surface-2: oklch(0.497 0.183 20.2);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.794 0.068 7.1);
  --accent: oklch(1.000 0 0);
  --accent-fg: oklch(0.418 0.158 20.7);
  --accent-2: oklch(0.503 0.144 250.3);
  --line: oklch(1 0 0 / 22%);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(1.000 0 0);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Staatliches", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-bayern-munich h1,
.theme-bayern-munich h2,
.theme-bayern-munich h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-bayern-munich { --font-ui: var(--font-display); }
.theme-bayern-munich h1, .theme-bayern-munich h2 { text-transform: uppercase; }
.theme-bayern-munich button { text-transform: uppercase; letter-spacing: 0.06em; }

.theme-bayern-munich { background-image: repeating-linear-gradient(45deg, oklch(1 0 0 / 4%) 0 26px, transparent 26px 52px), repeating-linear-gradient(-45deg, oklch(1 0 0 / 4%) 0 26px, transparent 26px 52px); }
.theme-bayern-munich h1 { letter-spacing: 0.04em; }
.theme-bayern-munich .label-caps { color: oklch(0.9 0.02 250); }

/* alt mode: auto-derived light variant */
.theme-bayern-munich.alt-mode {
  --bg: oklch(0.98 0.012 20.7);
  --surface: oklch(0.955 0.015 20.7);
  --surface-2: oklch(0.92 0.020 20.7);
  --fg: oklch(0.17 0.005 270);
  --fg-muted: oklch(0.46 0.01 270);
  --line: oklch(0.87 0.005 270);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --accent: oklch(0.52 0.080 0.0);
  --accent-fg: oklch(1 0 0);
  background-image: none;
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
